enum {
    SURFER_BRUCE_IRONS,
    SURFER_DONAVON_FRANKENREITER,
    SURFER_KALANI_ROBB,
    SURFER_KELLY_SLATER,
    SURFER_LISA_ANDERSEN,
    SURFER_NATHAN_FLETCHER,
    SURFER_ROB_MACHADO,
    SURFER_TOM_CARROL,
    SURFER_TOM_CURREN,
    SURFER_MISC_SURFER,
    SURFER_TRAVIS_PASTRANA,
    SURFER_TIKI_GOD,
    SURFER_TONY_HAWK,
    SURFER_SURFREAK,
    SURFER_LAST
};

enum
{
	ATTRIB_AIR,
	ATTRIB_SPEED,
	ATTRIB_ROTATE,
	ATTRIB_BALANCE,
	NUM_ATTRIBS
};

enum
{
	BOARD_1_ATTR,
	BOARD_2_ATTR,
	NUM_BOARDS_ATTRS
};

class SurferAttributes
{
public:

	SurferAttributes();

	int player_rotate;
	int player_speed;
	int player_balance;
	int player_air;

	int board_rotate;
	int board_speed;
	int board_balance;
	int board_air;

	int use_debug_values;

	int player_attribs[SURFER_LAST][NUM_ATTRIBS];
	int board_attribs[NUM_BOARDS_ATTRS][NUM_ATTRIBS];
};

SurferAttributes::SurferAttributes()
{
	use_debug_values = 0;

	player_rotate = 13;
	player_speed = 20;
	player_balance = 20;
	player_air = 13;

	board_rotate = 7;
	board_speed = 7;
	board_balance = 7;
	board_air = 7;

	int n, m;
	for (n = 0; n < SURFER_LAST; n++)
	{
		for (m = 0; m < NUM_ATTRIBS; m++)
		{
			player_attribs[n][ATTRIB_AIR] = player_air;
			player_attribs[n][ATTRIB_SPEED] = player_speed;
			player_attribs[n][ATTRIB_ROTATE] = player_rotate;
			player_attribs[n][ATTRIB_BALANCE] = player_balance;
		}
	}

	for (n = 0; n < NUM_BOARDS_ATTRS; n++)
	{
		for (m = 0; m < NUM_ATTRIBS; m++)
		{
			board_attribs[n][ATTRIB_AIR] = board_air;
			board_attribs[n][ATTRIB_SPEED] = board_speed;
			board_attribs[n][ATTRIB_ROTATE] = board_rotate;
			board_attribs[n][ATTRIB_BALANCE] = board_balance;
		}
	}
}
